<?php require __DIR__.'/config.php'; if (empty($_SESSION['pending_user'])) { header('Location:index.php'); exit; } if ($_SERVER['REQUEST_METHOD']==='POST') { check_csrf(); $stmt=$db->prepare('SELECT * FROM users WHERE id=?'); $stmt->execute([$_SESSION['pending_user']]); $user=$stmt->fetch(PDO::FETCH_ASSOC); if ($user && hash_equals(totp($user['totp_secret']), $_POST['code'])) { $_SESSION['user_id']=$_SESSION['pending_user']; header('Location:dashboard.php'); exit; } flash('OTP ist falsch. Aktueller Demo-Code: '.($user?totp($user['totp_secret']):'')); } page('<h1>OTP Authenticator</h1>'.show_flash().'<form method="post"><input type="hidden" name="csrf" value="'.h(csrf()).'"><label>OTP<input name="code" pattern="[0-9]{6}" required></label><button>Einloggen</button></form>'); ?>